function nav(){let t=T[g];return '<header><div class="navwrap"><a class="brand" href="index.html"><img src="assets/usfans-logo-v6.jpg" alt="USFans Sheett"></a><nav>'+LP[g].map((x,i)=>'<a class="'+(((Q==='home'&&i===0)||R[i].replace('.html','')===Q)?'on':'')+'" href="'+R[i]+'">'+x+'</a>').join('')+'</nav><a class="database" href="'+B+'">'+t.open+'</a><div class="language"><button>'+g.toUpperCase()+'⌄</button><div class="langs">'+Object.keys(LP).map(x=>'<button data-lang="'+x+'">'+x.toUpperCase()+' · '+LP[x][0]+'</button>').join('')+'</div></div></div></header>'}
function cats(){return '<div class="categories">'+K.map((x,i)=>'<a href="'+B+x[0]+'"><img src="assets/'+x[1]+'" alt="'+N[g][i]+'"><span>'+N[g][i]+' <b>→</b></span></a>').join('')+'</div>'}function products(n=P.length){return '<div class="products">'+P.slice(0,n).map(x=>'<a href="'+B+x[2]+'"><img src="'+B+x[3]+'" alt="'+x[0]+'"><div><strong>'+x[0]+'</strong><span>'+x[1]+' <b>↗</b></span></div></a>').join('')+'</div>'}
function faq(){let a=['USFans publicly presents a China buying-agent workflow for marketplace sourcing, warehouse photo confirmation and international shipping. This independent site is not an official USFans service.','No. It is a research layer for finding and comparing records. Verify the selected option on the live page.','Use visible photos to compare the item, variant, colour, label, surface and measurements where shown. They are evidence, not a quality or authenticity guarantee.','No. A photo set cannot inspect every hidden or future-use issue. Request clarification before parcel submission when a missing view matters.','Public information has described a return request of up to five days for eligible warehouse items. Rules, fees and conditions vary; check the current order page.','Product cost, domestic shipping, optional services and international parcel cost are separate. Destination, route, weight, dimensions and restrictions can change the total.','No. Route availability, timing, customs treatment, local rules and carrier handling can change. Confirm the current route information.','They go to the matching FindSpreadsheet category or product-detail page. This site does not process purchases, payments or shipping.'];return '<div class="faqpage">'+F[g].map((x,i)=>'<details '+(!i?'open':'')+'><summary>'+x+'</summary><p>'+a[i]+'</p></details>').join('')+'</div>'}
