function home(){let t=T[g];return nav()+'<main><section class="hero"><div class="heroimage"><img id="heroimg" src="assets/hub-hero-1-v10.jpg" alt="Product research"><div class="dots"><button data-slide="1" class="selected">01</button><button data-slide="2">02</button><button data-slide="3">03</button></div></div><div class="heroCopy"><p class="kicker">'+t.attrs[0]+'</p><h1>'+t.hero+'</h1><p>'+t.intro+'</p><div class="actions"><a href="categories.html">'+t.browse+'</a><a href="articles.html">'+t.read+'</a></div></div></section><section class="query"><div><p class="kicker">'+t.find+'</p><h2>'+t.start+'</h2></div><form class="search" action="'+B+'search.html"><label for="q">'+t.search+'</label><div><input id="q" name="keywords" placeholder="'+t.ph+'" required><input name="channelid" value="2" type="hidden"><button>'+t.search.split(' ')[0]+'</button></div></form></section><section class="attributes">'+t.attrs.map(x=>'<span>'+x+'</span>').join('')+'</section><section class="block categoryblock"><div class="title"><div><p class="kicker">'+t.cat+'</p><h2>'+t.dir+'</h2></div><p>'+t.catnote+'</p></div>'+cats()+'</section><section class="explain"><div><p class="kicker">'+t.how+'</p><h2>'+t.howh+'</h2><p>'+t.howp+'</p><a href="articles.html">'+t.read+' →</a></div><ol>'+t.steps.map((x,i)=>'<li><b>0'+(i+1)+'</b><strong>'+x[0]+'</strong><span>'+x[1]+'</span></li>').join('')+'</ol></section><section class="toolkit"><div class="title"><div><p class="kicker">'+t.kit+'</p><h2>'+t.kith+'</h2></div><p>'+t.kitp+'</p></div><div class="toolgrid"><div class="check"><h3>'+t.check+'</h3>'+t.checks.map(x=>'<label><input type="checkbox">'+x+'</label>').join('')+'<button class="reset">'+t.reset+'</button></div><form class="weight"><h3>'+t.weight+'</h3><label>'+t.actual+'<input id="actual" type="number" step="0.1" value="1.2"></label><label>'+t.dims+'<span><input id="length" type="number" value="40"><input id="width" type="number" value="30"><input id="height" type="number" value="20"></span></label><button type="button" id="calculate">'+t.estimate+'</button><p id="weightresult">'+t.example+' 4 kg</p></form></div></section><section class="block picks"><div class="title"><div><p class="kicker">'+t.latest+'</p><h2>'+t.price+'</h2></div><a href="details.html">'+t.all+'</a></div>'+products(4)+'</section><section class="faqhome fullfaq"><div class="faqintro"><p class="kicker">'+LP[g][4]+'</p><h2>'+t.faqh+'</h2><p>'+t.faqp+'</p></div>'+faq()+'</section></main>'+foot()}
function render(){let t=T[g];document.documentElement.lang=g;let body;if(Q==='home')body=home();else{let i={categories:0,details:1,articles:2,faq:3}[Q],content=[cats(),products(),article(),faq()][i];body=nav()+'<main><section class="pagehero"><p class="kicker">USFans Sheett</p><h1>'+t.pages[i][0]+'</h1><p>'+t.pages[i][1]+'</p></section><section class="pagebody">'+content+'</section></main>'+foot()}document.body.innerHTML=body;document.querySelectorAll('[data-lang]').forEach(x=>x.onclick=()=>{g=x.dataset.lang;localStorage.setItem('usfans-v12-lang',g);render()});if(Q==='home'){let pics=['assets/hub-hero-1-v10.jpg','assets/hub-hero-2-v10.jpg','assets/hub-hero-3-v10.jpg'];document.querySelectorAll('[data-slide]').forEach(x=>x.onclick=()=>{document.querySelector('#heroimg').src=pics[x.dataset.slide-1]});document.querySelector('.reset').onclick=()=>document.querySelectorAll('.check input').forEach(x=>x.checked=false);document.querySelector('#calculate').onclick=()=>{let a=+document.querySelector('#actual').value||0,v=(+document.querySelector('#length').value||0)*(+document.querySelector('#width').value||0)*(+document.querySelector('#height').value||0)/6000;document.querySelector('#weightresult').textContent=t.example+' '+Math.max(a,v).toFixed(2)+' kg'}}}render();
function article(){let a=T[g].article;if(g!=='en')return '<article class="article"><p class="kicker">'+T[g].read+'</p><h2>'+a[0]+'</h2><p class="source-note">'+a.slice(1).join('</p><p>')+'</p><p><a href="'+B+'">'+T[g].search+' ↗</a></p></article>';return '<article class="article"><p class="kicker">SEO Article · Independent research note</p><h2>How to Use USFans for Product-Link Research, QC Review and Parcel Planning</h2><p class="source-note">Research basis: USFans public-facing information reviewed on 28 September 2026. This is an independent educational article, not an official USFans policy page. Product, return, shipping and customs terms must always be reconfirmed in the live account and order flow.</p><p>People often treat an agent-style shopping workflow as though it were a normal online store: choose an item, pay once, and wait for delivery. That mental model is where many bad decisions begin. USFans publicly presents itself as a China buying agent for marketplaces such as Taobao, 1688 and Weidian, with product sourcing, warehouse photo confirmation and international shipping. In practice, that means the buyer is managing a sequence of separate decisions rather than making one finished retail purchase. The product listing, domestic purchase, warehouse check, return decision, parcel build and international route each carry different information and different risks.</p><p>The useful role of a spreadsheet or directory is therefore research. It helps you discover a product page and compare a visible title, price and photo. It does not prove that a seller still has stock, that your variant is available, or that a delivered item will match every expectation. A strong workflow leaves room for the live listing and warehouse evidence to disagree with an older saved link.</p><h3>1. Begin with a link, then verify the live listing</h3><p>USFans is built around sourcing from external Chinese-marketplace links. Before submitting any link, open the source listing yourself. Read the title, identify the seller, inspect every selectable size or colour and compare the photographs with the option you intend to choose. If there is a measurement chart, save the measurements instead of relying on a broad size name. A label such as “large” is not a universal specification across sellers or categories.</p><p>Price deserves the same care. The headline amount can represent a deposit, a small option, an accessory or a promotion rather than the configuration you intend to buy. Check whether the selected variant changes the amount. Keep a simple record of product cost, domestic shipping shown on the listing and optional services. This is more useful than one total because it reveals which part of an estimate has changed. A directory can link to FindSpreadsheet records, but the current listing and order page remain the places to reconfirm the amount.</p><h3>2. Treat warehouse QC as visible evidence, not certification</h3><p>USFans publicly promotes quality-checking and high-definition photo confirmation for purchases. This creates a pause between seller dispatch and international shipping. That pause is valuable, but it is not a guarantee of authenticity, durability, fit, material composition or a perfect product. Photos show what is visible in the supplied frames at one moment. They cannot fully answer questions about long-term wear, hidden construction, future colour transfer or details outside the camera angle.</p><p>A disciplined QC review is specific. Check that the item and selected variant appear to match the order. Look at colour, visible size label, logo or print placement where relevant, seams, panels, sole shape, hardware, accessories and obvious surface damage. If measurements matter, compare a visible tape measurement with the seller chart and allow ordinary manual-measurement variation. If one missing view would change your decision, request clarification before parcel submission. Asking a precise question early is better than interpreting a blurry detail after items are consolidated.</p><p>Do not turn a checklist into a promise. A tick beside “stitching checked” only means visible stitching was reviewed. It does not create a quality grade. This distinction is good practice for buyers and credible search content alike: it describes a repeatable decision process without claiming outcomes an independent guide cannot control.</p><h3>3. Know the return boundary before you need it</h3><p>USFans public information has described a post-arrival return-request window of up to five days for eligible warehouse items. Treat the words “request” and “eligible” as important. Seller rules, item type, condition, domestic shipping and order-specific terms can affect whether a return can proceed and what it costs. A guide should never present a historic five-day reference as a universal refund guarantee. The practical lesson is simple: review warehouse photos promptly, keep the order record and decide while the applicable window is still open.</p><p>When uncertain, separate two questions. First, does the warehouse evidence show the item you intended to buy? Second, do you still want it at the confirmed product price and likely parcel cost? Buyers can focus only on a perceived flaw and miss the larger issue that the item no longer fits the total plan. Returning can be sensible even when QC looks acceptable; keeping can be sensible when a small visible variation does not change your use case. Use your own criteria rather than assuming someone else can make that decision for you.</p><h3>4. Parcel planning is where the total changes</h3><p>USFans also markets international shipping and global delivery coverage. That description does not make final freight predictable from the product price alone. International cost can depend on destination, route availability, parcel weight, dimensions, chargeable-weight rules, service restrictions, packing choices and the timing of a quotation. A cheap product can become an expensive parcel component if it is bulky, boxed or difficult to consolidate. A higher-priced item may add relatively little shipping cost if it fits an existing parcel efficiently.</p><p>Plan only after warehouse decisions are stable. List the items you intend to ship, note anything with a box or fragile shape and decide whether original packaging is necessary. When the system shows actual weight or a route quote, compare it with your working estimate. If the amount does not make sense, pause and ask what is included rather than assuming an error or a final promise. Route rules and customs requirements vary by destination, so no responsible article can guarantee delivery times, duties, declarations or clearance outcomes.</p><h3>5. Keep claims, evidence and expectations separate</h3><p>The easiest way to reduce confusion is to label each statement by its source. A seller listing is a seller claim. A warehouse photograph is visible evidence. A displayed route quote is a current estimate or charge in the relevant order flow. Your expectation of fit, quality or delivery timing is personal judgement. Mixing those categories creates false certainty. Keeping them separate makes it easier to identify what needs another check.</p><p>This approach also improves how you use FindSpreadsheet. Use the database to locate varied products and open the current page. Treat a record image and USD display as a starting point rather than permanent stock data. Then follow the live order process, review warehouse evidence and make parcel decisions using current information. It is slower than clicking the first appealing thumbnail, but it produces a decision you can explain to yourself later.</p><h3>A practical final checklist</h3><ol><li>Open the live product listing and verify selected variant, size information and visible price.</li><li>Record product cost separately from domestic and international shipping considerations.</li><li>Review warehouse photos promptly and request clarification if a missing angle matters.</li><li>Read current return-request eligibility before assuming a deadline applies.</li><li>Build a parcel only after keep-or-return choices are settled.</li><li>Recheck route cost, restrictions and destination requirements in the live order flow before paying.</li></ol><p>The core idea is straightforward: USFans can be part of a structured buying workflow, but it does not remove the need for research. Links help you discover, QC photos help you inspect what is visible and parcel tools help you plan. The buyer still needs to verify each stage and accept that listing information, seller stock, shipping conditions and import treatment can change. That is the honest boundary that makes an independent guide useful.</p><p><a href="'+B+'">Browse current FindSpreadsheet product details ↗</a></p></article>'}
function render(){let t=T[g],body;if(Q==='home')body=home().replace('</main>','<section class="pagebody seo-on-home">'+article()+'</section></main>');else{let i={categories:0,details:1,articles:2,faq:3}[Q],content=[cats(),products(),article(),faq()][i];body=nav()+'<main><section class="pagehero"><p class="kicker">USFans Sheett</p><h1>'+t.pages[i][0]+'</h1><p>'+t.pages[i][1]+'</p></section><section class="pagebody">'+content+'</section></main>'+foot()}document.documentElement.lang=g;document.body.innerHTML=body;document.querySelectorAll('[data-lang]').forEach(x=>x.onclick=()=>{g=x.dataset.lang;localStorage.setItem('usfans-v12-lang',g);render()});if(Q==='home'){let pics=['assets/hub-hero-1-v10.jpg','assets/hub-hero-2-v10.jpg','assets/hub-hero-3-v10.jpg'];document.querySelectorAll('[data-slide]').forEach(x=>x.onclick=()=>document.querySelector('#heroimg').src=pics[x.dataset.slide-1]);document.querySelector('.reset').onclick=()=>document.querySelectorAll('.check input').forEach(x=>x.checked=false);document.querySelector('#calculate').onclick=()=>{let a=+document.querySelector('#actual').value||0,v=(+document.querySelector('#length').value||0)*(+document.querySelector('#width').value||0)*(+document.querySelector('#height').value||0)/6000;document.querySelector('#weightresult').textContent=t.example+' '+Math.max(a,v).toFixed(2)+' kg'}}
}
render();
const LX={
de:{h:['1. Produktlink-Recherche','2. QC-Prüfung','3. Rückgabe und Zeitpunkt','4. Paketplanung','5. Klare Belege','Praktische Abschluss-Checkliste'],q:['USFans beschreibt öffentlich einen China-Buying-Agent-Ablauf für Marktplätze wie Taobao, 1688 und Weidian, mit Lagerfoto-Bestätigung und internationalem Versand. Diese unabhängige Seite ist kein offizieller USFans-Dienst.','Nein. Es ist eine Rechercheebene zum Finden und Vergleichen von Datensätzen. Prüfe die gewählte Option auf der aktuellen Produktseite.','Nutze sichtbare Fotos zum Vergleich von Artikel, Variante, Farbe, Etikett, Oberfläche und gezeigten Maßen. Sie sind Belege, keine Qualitäts- oder Echtheitsgarantie.','Nein. Ein Fotosatz kann nicht jeden verdeckten oder erst später auftretenden Punkt prüfen. Bitte vor der Paketeinreichung um Klärung, wenn eine Ansicht wichtig ist.','Öffentliche Informationen beschreiben für berechtigte Lagerartikel teils eine Rückgabeanfrage von bis zu fünf Tagen. Regeln, Gebühren und Bedingungen können abweichen; prüfe die aktuelle Bestellseite.','Produktkosten, Inlandsversand, optionale Dienste und internationale Paketkosten sind getrennt. Zielort, Route, Gewicht, Maße und Beschränkungen können die Summe verändern.','Nein. Routenverfügbarkeit, Zeit, Zollbehandlung, lokale Regeln und Carrier können sich ändern. Bestätige die aktuelle Routeninformation.','Sie führen zur passenden FindSpreadsheet-Kategorie oder Produktdetailseite. Diese Seite verarbeitet keine Käufe, Zahlungen oder Sendungen.'],m:['Ein gespeicherter Link ist kein Lagerbestand. Öffne das Angebot erneut, wenn du bestellen möchtest, und behandle Screenshots oder frühere Preise nur als Ausgangspunkt.','Vergleiche die Auswahl mit dem Foto, nicht nur mit dem Namen. Gerade Farbe, Materialoptik, Logo-Position und Größenangabe können zwischen Varianten abweichen.','Bitte um eine konkrete Ansicht oder Messung, wenn sie deine Entscheidung ändern würde. Allgemeine Fragen liefern oft keine verwertbare Antwort.','Eine Rückgabeanfrage ist keine automatische Erstattung. Prüfe Berechtigung, Verkäuferregeln, Frist und mögliche Inlandskosten vor der Entscheidung.','Ein Karton, eine fragile Form oder unnötige Verpackung kann das berechenbare Gewicht stärker beeinflussen als der Warenpreis.','Eine angezeigte Route ist eine Momentaufnahme. Prüfe Zielort und Restriktionen erneut kurz vor der Zahlung.','Trenne Verkäuferbehauptung, sichtbaren Lagerbeleg, aktuelle Routenberechnung und deine eigene Erwartung. So wird klar, was noch überprüft werden muss.']},
fr:{h:['1. Recherche de liens produit','2. Vérification QC','3. Retour et délai','4. Planification du colis','5. Des preuves claires','Liste finale pratique'],q:['USFans présente publiquement un parcours d’agent d’achat chinois pour des places de marché comme Taobao, 1688 et Weidian, avec photos d’entrepôt et expédition internationale. Ce site indépendant n’est pas un service officiel.','Non. C’est une couche de recherche pour trouver et comparer des fiches. Vérifiez l’option choisie sur la page produit actuelle.','Utilisez les photos visibles pour comparer l’article, la variante, la couleur, l’étiquette, la surface et les mesures affichées. Ce sont des preuves, pas une garantie de qualité ou d’authenticité.','Non. Un ensemble de photos ne peut pas contrôler chaque problème caché ou futur. Demandez une précision avant de soumettre le colis si une vue vous importe.','Des informations publiques décrivent une demande de retour jusqu’à cinq jours pour certains articles éligibles. Règles, frais et conditions varient : vérifiez la commande actuelle.','Le produit, l’envoi national, les services optionnels et le colis international sont distincts. Destination, route, poids, dimensions et restrictions peuvent modifier le total.','Non. Disponibilité des routes, délai, douane, règles locales et transporteur peuvent changer. Confirmez la route actuelle.','Ils mènent à la catégorie ou à la fiche FindSpreadsheet correspondante. Ce site ne traite ni achats, ni paiements, ni expéditions.'],m:['Un lien enregistré ne prouve pas le stock. Rouvrez la fiche avant toute décision et considérez ancien prix ou capture comme un simple point de départ.','Comparez l’option avec les photos, pas seulement avec son nom. Couleur, finition, position d’un détail et taille peuvent varier.','Demandez un angle ou une mesure précise si cela peut modifier votre décision ; une question vague produit rarement une réponse exploitable.','Une demande de retour n’est pas un remboursement automatique. Vérifiez éligibilité, règles vendeur, délai et coûts nationaux éventuels.','Une boîte, une forme fragile ou un emballage inutile peut augmenter davantage le poids facturable que le prix du produit.','Une route affichée est une photographie du moment. Vérifiez de nouveau destination et restrictions juste avant le paiement.','Séparez affirmation vendeur, preuve d’entrepôt, devis actuel et attente personnelle : vous verrez immédiatement ce qui doit encore être vérifié.']},
es:{h:['1. Investigación de enlaces','2. Revisión QC','3. Devoluciones y plazos','4. Planificación del paquete','5. Evidencia clara','Lista final práctica'],q:['USFans presenta públicamente un proceso de agente de compra chino para mercados como Taobao, 1688 y Weidian, con fotos de almacén y envío internacional. Este sitio independiente no es un servicio oficial.','No. Es una capa de investigación para encontrar y comparar fichas. Verifica la opción elegida en la página actual.','Usa fotos visibles para comparar artículo, variante, color, etiqueta, superficie y medidas mostradas. Son evidencia, no garantía de calidad ni autenticidad.','No. Un conjunto de fotos no puede inspeccionar cada problema oculto o futuro. Pide aclaración antes de enviar el paquete si una vista importa.','La información pública describe una solicitud de devolución de hasta cinco días para artículos elegibles. Reglas, tarifas y condiciones varían; revisa el pedido actual.','Producto, envío nacional, servicios opcionales y paquete internacional son conceptos separados. Destino, ruta, peso, dimensiones y restricciones cambian el total.','No. Disponibilidad de ruta, tiempo, aduana, normas locales y transportista pueden cambiar. Confirma la ruta actual.','Van a la categoría o ficha correspondiente de FindSpreadsheet. Este sitio no procesa compras, pagos ni envíos.'],m:['Un enlace guardado no demuestra stock. Abre de nuevo la ficha antes de decidir y trata precios o capturas antiguas solo como punto de partida.','Compara la opción con las fotos, no solo con el nombre. Color, acabado, posición de detalles y talla pueden variar.','Pide un ángulo o una medida concreta si puede cambiar tu decisión; una pregunta general rara vez da una respuesta útil.','Una solicitud de devolución no es reembolso automático. Comprueba elegibilidad, reglas del vendedor, plazo y posibles costes nacionales.','Una caja, forma frágil o embalaje innecesario puede afectar más al peso facturable que el precio del producto.','Una ruta visible es una foto del momento. Comprueba destino y restricciones de nuevo justo antes de pagar.','Separa afirmación del vendedor, evidencia de almacén, cotización actual y expectativa personal: así sabrás qué falta comprobar.']},
it:{h:['1. Ricerca dei link prodotto','2. Revisione QC','3. Resi e tempistiche','4. Pianificazione del pacco','5. Prove chiare','Checklist finale pratica'],q:['USFans presenta pubblicamente un flusso di agente d’acquisto cinese per marketplace come Taobao, 1688 e Weidian, con foto di magazzino e spedizione internazionale. Questo sito indipendente non è un servizio ufficiale.','No. È uno strumento di ricerca per trovare e confrontare schede. Verifica l’opzione scelta sulla pagina prodotto attuale.','Usa le foto visibili per confrontare articolo, variante, colore, etichetta, superficie e misure mostrate. Sono prove, non garanzia di qualità o autenticità.','No. Un set fotografico non può controllare ogni problema nascosto o futuro. Chiedi chiarimenti prima di inviare il pacco se una vista è importante.','Informazioni pubbliche descrivono una richiesta di reso fino a cinque giorni per articoli idonei. Regole, commissioni e condizioni variano; controlla l’ordine attuale.','Prodotto, spedizione nazionale, servizi opzionali e pacco internazionale sono separati. Destinazione, rotta, peso, dimensioni e restrizioni cambiano il totale.','No. Disponibilità della rotta, tempi, dogana, regole locali e vettore possono cambiare. Conferma la rotta attuale.','Portano alla categoria o scheda FindSpreadsheet corrispondente. Questo sito non elabora acquisti, pagamenti o spedizioni.'],m:['Un link salvato non dimostra disponibilità. Riapri la scheda prima di decidere e considera prezzi o screenshot passati solo come punto di partenza.','Confronta l’opzione con le foto, non soltanto con il nome. Colore, finitura, posizione dei dettagli e taglia possono variare.','Chiedi un’angolazione o una misura precisa se può cambiare la decisione; una domanda generica raramente produce una risposta utile.','Una richiesta di reso non è un rimborso automatico. Verifica idoneità, regole venditore, termine e possibili costi nazionali.','Scatola, forma fragile o imballaggio inutile possono influire sul peso tassabile più del prezzo dell’articolo.','Una rotta mostrata è una fotografia del momento. Ricontrolla destinazione e restrizioni subito prima del pagamento.','Separa affermazione del venditore, prova di magazzino, preventivo attuale e aspettativa personale: così saprai cosa va ancora verificato.']},
pt:{h:['1. Pesquisa de links','2. Revisão QC','3. Devoluções e prazo','4. Planejamento da encomenda','5. Evidência clara','Checklist final prático'],q:['A USFans apresenta publicamente um fluxo de agente de compras chinês para mercados como Taobao, 1688 e Weidian, com fotos de armazém e envio internacional. Este site independente não é um serviço oficial.','Não. É uma camada de pesquisa para encontrar e comparar fichas. Verifique a opção escolhida na página atual.','Use fotos visíveis para comparar item, variante, cor, etiqueta, superfície e medidas mostradas. São evidência, não garantia de qualidade ou autenticidade.','Não. Um conjunto de fotos não pode inspecionar todo problema oculto ou futuro. Peça esclarecimento antes do envio se uma vista for importante.','Informações públicas descrevem pedido de devolução de até cinco dias para itens elegíveis. Regras, taxas e condições variam; confira o pedido atual.','Produto, frete nacional, serviços opcionais e encomenda internacional são separados. Destino, rota, peso, dimensões e restrições alteram o total.','Não. Disponibilidade da rota, prazo, alfândega, regras locais e transportadora podem mudar. Confirme a rota atual.','Eles levam à categoria ou ficha FindSpreadsheet correspondente. Este site não processa compras, pagamentos ou envios.'],m:['Um link salvo não prova estoque. Abra a listagem novamente antes de decidir e trate preço ou captura antigos apenas como ponto de partida.','Compare a opção às fotos, não apenas ao nome. Cor, acabamento, posição de detalhes e tamanho podem variar.','Peça um ângulo ou medida específica se isso puder mudar sua decisão; uma pergunta geral raramente gera resposta útil.','Pedido de devolução não é reembolso automático. Verifique elegibilidade, regras do vendedor, prazo e possíveis custos nacionais.','Caixa, formato frágil ou embalagem desnecessária podem afetar o peso cobrável mais que o preço do produto.','Uma rota exibida é uma fotografia do momento. Verifique destino e restrições novamente imediatamente antes de pagar.','Separe alegação do vendedor, evidência do armazém, cotação atual e expectativa pessoal; assim ficará claro o que ainda precisa ser conferido.']},
nl:{h:['1. Onderzoek naar productlinks','2. QC-beoordeling','3. Retour en termijn','4. Pakketplanning','5. Duidelijk bewijs','Praktische eindchecklist'],q:['USFans presenteert publiekelijk een Chinese koopagentwerkwijze voor marktplaatsen zoals Taobao, 1688 en Weidian, met magazijnfoto’s en internationale verzending. Deze onafhankelijke site is geen officiële dienst.','Nee. Het is een onderzoekslaag om vermeldingen te vinden en vergelijken. Controleer de gekozen optie op de actuele productpagina.','Gebruik zichtbare foto’s om item, variant, kleur, label, oppervlak en getoonde maten te vergelijken. Het is bewijs, geen kwaliteits- of authenticiteitsgarantie.','Nee. Een fotoset kan niet ieder verborgen of toekomstig probleem controleren. Vraag verduidelijking vóór inzending wanneer een aanzicht belangrijk is.','Openbare informatie beschrijft soms een retourverzoek tot vijf dagen voor geschikte artikelen. Regels, kosten en voorwaarden verschillen; controleer de actuele bestelling.','Product, binnenlandse verzending, optionele diensten en internationaal pakket zijn apart. Bestemming, route, gewicht, maten en beperkingen kunnen het totaal veranderen.','Nee. Routebeschikbaarheid, tijd, douane, lokale regels en vervoerder kunnen veranderen. Bevestig actuele routeinformatie.','Ze gaan naar de passende FindSpreadsheet-categorie of productdetailpagina. Deze site verwerkt geen aankopen, betalingen of verzending.'],m:['Een opgeslagen link bewijst geen voorraad. Open de vermelding opnieuw voor je beslist en gebruik oude prijs of schermafbeelding slechts als beginpunt.','Vergelijk de optie met foto’s, niet alleen met de naam. Kleur, afwerking, positie van details en maat kunnen verschillen.','Vraag om een concrete hoek of maat wanneer dat je besluit kan wijzigen; een algemene vraag geeft zelden bruikbaar antwoord.','Een retourverzoek is geen automatische terugbetaling. Controleer geschiktheid, verkopersregels, termijn en mogelijke binnenlandse kosten.','Een doos, breekbare vorm of onnodige verpakking kan het factureerbare gewicht sterker beïnvloeden dan de productprijs.','Een zichtbare route is een momentopname. Controleer bestemming en beperkingen opnieuw vlak voor betaling.','Houd verkopersclaim, magazijnbewijs, actuele offerte en persoonlijke verwachting apart; dan zie je wat nog gecontroleerd moet worden.']},
pl:{h:['1. Research linków produktów','2. Kontrola QC','3. Zwroty i terminy','4. Planowanie paczki','5. Jasne dowody','Praktyczna lista końcowa'],q:['USFans publicznie przedstawia chiński proces agenta zakupowego dla marketplace’ów takich jak Taobao, 1688 i Weidian, ze zdjęciami magazynowymi i wysyłką międzynarodową. Ta niezależna strona nie jest usługą oficjalną.','Nie. To warstwa researchu do znajdowania i porównywania ofert. Sprawdź wybraną opcję na aktualnej stronie produktu.','Używaj widocznych zdjęć do porównania produktu, wariantu, koloru, metki, powierzchni i pokazanych wymiarów. To dowód, nie gwarancja jakości ani autentyczności.','Nie. Zestaw zdjęć nie sprawdzi każdego ukrytego lub przyszłego problemu. Poproś o wyjaśnienie przed zgłoszeniem paczki, gdy widok ma znaczenie.','Publiczne informacje opisywały wniosek o zwrot do pięciu dni dla kwalifikujących się produktów. Zasady, opłaty i warunki się różnią; sprawdź aktualne zamówienie.','Produkt, wysyłka krajowa, usługi opcjonalne i paczka międzynarodowa to oddzielne koszty. Kraj, trasa, waga, wymiary i ograniczenia zmieniają sumę.','Nie. Dostępność trasy, czas, odprawa celna, lokalne zasady i przewoźnik mogą się zmienić. Potwierdź aktualną trasę.','Prowadzą do pasującej kategorii lub strony szczegółów FindSpreadsheet. Ta strona nie obsługuje zakupów, płatności ani wysyłki.'],m:['Zapisany link nie potwierdza stanu magazynowego. Otwórz ofertę ponownie przed decyzją, a dawną cenę lub zrzut traktuj tylko jako punkt startowy.','Porównuj wariant ze zdjęciami, a nie wyłącznie z nazwą. Kolor, wykończenie, pozycja detali i rozmiar mogą się różnić.','Poproś o konkretny kąt lub wymiar, jeśli może zmienić decyzję; ogólne pytanie rzadko daje użyteczną odpowiedź.','Wniosek o zwrot nie jest automatycznym zwrotem pieniędzy. Sprawdź kwalifikację, zasady sprzedawcy, termin i możliwe koszty krajowe.','Pudełko, delikatny kształt lub zbędne opakowanie może mocniej wpłynąć na wagę rozliczeniową niż cena produktu.','Widoczna trasa jest obrazem chwili. Sprawdź kraj docelowy i ograniczenia ponownie tuż przed płatnością.','Oddziel twierdzenie sprzedawcy, dowód magazynowy, aktualną wycenę i własne oczekiwanie; wtedy wiadomo, co trzeba jeszcze sprawdzić.']}
};
function localizeLong(){if(g==='en')return;let x=LX[g],a=T[g].article,art=document.querySelector('.article');if(art)art.innerHTML='<p class="kicker">'+T[g].read+' · '+T[g].research+'</p><h2>'+a[0]+'</h2><p class="source-note">'+a[1]+'</p><h3>'+x.h[0]+'</h3><p>'+a[2]+'</p><p>'+a[3]+'</p><p>'+x.m[0]+'</p><p>'+x.m[1]+'</p><h3>'+x.h[1]+'</h3><p>'+a[4]+'</p><p>'+x.m[2]+'</p><h3>'+x.h[2]+'</h3><p>'+a[5]+'</p><p>'+x.m[3]+'</p><h3>'+x.h[3]+'</h3><p>'+a[6]+'</p><p>'+x.m[4]+'</p><p>'+x.m[5]+'</p><h3>'+x.h[4]+'</h3><p>'+a[7]+'</p><p>'+x.m[6]+'</p><h3>'+x.h[5]+'</h3><ol><li>'+x.m[0]+'</li><li>'+x.m[1]+'</li><li>'+x.m[2]+'</li><li>'+x.m[3]+'</li><li>'+x.m[4]+'</li><li>'+x.m[5]+'</li></ol><p><a href="'+B+'">'+T[g].search+' ↗</a></p>';document.querySelectorAll('.faqpage').forEach(box=>box.innerHTML=x.q.map((z,i)=>'<details '+(!i?'open':'')+'><summary>'+x.h[Math.min(i,5)]+' · '+F[g][i]+'</summary><p>'+z+'</p></details>').join(''))}
